// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Random;

import org.junit.jupiter.api.Test;

/**
 * The design's simulation matrix, driven directly against the model API with seeded generators: challenger-to-
 * incumbent runtime ratios {0.25, 0.8, 1.0, 1.2, 12, 1000} under lognormal noise and heavy-tail (GC-like) outliers.
 * Asserted properties: predictive-interval calibration on completed draws, no false displacement inside the margin, a
 * genuinely faster challenger displacing within a bounded number of observations, and — the headline of the whole
 * redesign — grossly slow rivals rejected from censored evidence alone, without one full completion.
 */
class LmdbNativeCostModelSimulationTest {

	private static final double INCUMBENT_NANOS = 1_000_000.0;
	private static final double SIGMA = 0.3;

	private static LmdbNativeAdaptiveCostModel model(LmdbNativeStoreCostModel store) {
		return new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
	}

	private static LmdbNativeCostEstimate estimate(String family) {
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, 100);
		return new LmdbNativeCostEstimate(LmdbNativePhysicalVariantKey.builder(family).build(),
				LmdbNativeCostVector.zero(), vector, 100, 0.1);
	}

	@Test
	void predictiveIntervalsStayCalibratedUnderLognormalAndHeavyTailNoise() {
		for (boolean heavyTail : new boolean[] { false, true }) {
			LmdbNativeAdaptiveCostModel model = model(new LmdbNativeStoreCostModel());
			LmdbNativeCostEstimate arm = estimate("incumbent");
			Random random = new Random(11);
			int warm = 60;
			for (int i = 0; i < warm; i++) {
				model.record(arm, arm.total(), draw(random, 1.0, heavyTail), true);
			}
			int covered = 0;
			int draws = 400;
			for (int i = 0; i < draws; i++) {
				LmdbNativeCostPrediction prediction = model.predict(arm);
				double actual = draw(random, 1.0, heavyTail);
				if (actual >= prediction.low95Nanos() && actual <= prediction.high95Nanos()) {
					covered++;
				}
				model.record(arm, arm.total(), actual, true);
			}
			double coverage = covered / (double) draws;
			assertTrue(coverage >= 0.90, "95% predictive coverage must not undercover: " + coverage
					+ (heavyTail ? " (heavy tail)" : ""));
		}
	}

	@Test
	void displacementFiresForRealGapsAndNeverInsideTheMargin() {
		double logGamma = LmdbNativePosteriorConfig.defaults().displacementLogGamma();
		for (double ratio : new double[] { 0.25, 0.8, 1.0, 1.2 }) {
			LmdbNativeAdaptiveCostModel model = model(new LmdbNativeStoreCostModel());
			LmdbNativeCostEstimate incumbent = estimate("incumbent");
			LmdbNativeCostEstimate challenger = estimate("challenger");
			Random random = new Random(23);
			int displacedAt = -1;
			for (int i = 0; i < 60; i++) {
				model.record(incumbent, incumbent.total(), draw(random, 1.0, false), true);
				model.record(challenger, challenger.total(), draw(random, ratio, false), true);
				if (displacedAt < 0 && LmdbNativeCostPrediction.displaces(model.predict(challenger),
						model.predict(incumbent), logGamma)) {
					displacedAt = i + 1;
				}
			}
			if (ratio <= 0.5) {
				assertTrue(displacedAt > 0 && displacedAt <= 30,
						"a 4x faster challenger must displace within 30 interleaved samples, took " + displacedAt);
			} else if (ratio >= 1.0) {
				assertTrue(displacedAt < 0,
						"a challenger at ratio " + ratio + " must never displace at margin " + logGamma);
			}
		}
	}

	@Test
	void grosslySlowRivalsAreRejectedFromCensoredEvidenceAloneWithoutOneCompletion() {
		for (double ratio : new double[] { 12.0, 1000.0 }) {
			LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
			LmdbNativeAdaptiveCostModel model = model(store);
			LmdbNativeCostEstimate incumbent = estimate("incumbent");
			LmdbNativeCostEstimate rival = estimate("rival");
			Random random = new Random(37);
			for (int i = 0; i < 30; i++) {
				model.record(incumbent, incumbent.total(), draw(random, 1.0, false), true);
			}
			LmdbNativeRegimeKey regime = model.currentRegime();
			long deadline = (long) (INCUMBENT_NANOS / LmdbNativeProbeConfig.defaults().gamma());
			// the rival never completes inside the deadline at these ratios: censor it (as executeProbe would)
			LmdbNativeAdaptiveCostModel.CensorResult censor = model.recordCensored(rival, deadline, rival.total(),
					regime);
			assertTrue(censor.recorded(), "a policy censor is first-class evidence");
			store.probeScheduler().censored(rival.variantKey(), regime, 0L, censor.severeMiss());

			assertFalse(store.probeScheduler().mayProbe(rival.variantKey(), regime, 0L),
					"one censor fulfills the obligation — no immediate re-probe at ratio " + ratio);
			LmdbNativeCostPrediction after = model.predict(rival);
			assertTrue(after.expectedNanos() > deadline * 0.5,
					"the censored posterior must not price the rival below the deadline it failed: "
							+ after.expectedNanos());
			assertFalse(LmdbNativeCostPrediction.displaces(after, model.predict(incumbent),
					LmdbNativePosteriorConfig.defaults().displacementLogGamma()),
					"a censored-only rival can never displace the incumbent");
		}
	}

	private static double draw(Random random, double ratio, boolean heavyTail) {
		double value = INCUMBENT_NANOS * ratio * Math.exp(SIGMA * random.nextGaussian());
		if (heavyTail && random.nextDouble() < 0.05) {
			value *= 20.0; // GC-like pause
		}
		return value;
	}
}
